{
  "ontology_name": "Core_Ontology",
  "version": "2.0",
  "language": "en",
  "source_type": "technical PDF",
  "source_title": "hypertherm_powermax30_air_service_manual_rev4_808850.pdf",
  "nodes": {
    "Component": [
      {
        "component_id": "comp_power_supply",
        "name": "Power supply",
        "description": "The power supply containing the air pressure test connections and power board.",
        "category": "power"
      },
      {
        "component_id": "comp_fan",
        "name": "Fan",
        "description": "The fan, which can affect the appearance of leaks during leak testing.",
        "category": "cooling"
      },
      {
        "component_id": "comp_air_compressor",
        "name": "Air compressor",
        "description": "The compressor that supplies air; the manual directs checking its voltage if air pressure is low.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_compressor_driver_board",
        "name": "Compressor-driver board",
        "description": "The board associated with the air compressor and its diagnostic LED.",
        "category": "electrical"
      },
      {
        "component_id": "comp_diagnostic_led_d5",
        "name": "Diagnostic LED (D5)",
        "description": "The diagnostic LED on the compressor-driver board.",
        "category": "diagnostic"
      },
      {
        "component_id": "comp_solenoid_valve",
        "name": "Solenoid valve",
        "description": "The valve with gas hoses connected to each side, included in the gas supply line leak checks.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_air_filter_assembly",
        "name": "Air filter assembly",
        "description": "The assembly into which the filter bowl screws, included in the gas supply line leak checks.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_filter_bowl",
        "name": "Filter bowl",
        "description": "The bowl that screws into the air filter assembly and connects to the drain hose.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_drain_hose",
        "name": "Drain hose",
        "description": "The hose connected to the bottom of the filter bowl and routed through the base of the power supply.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_power_board",
        "name": "Power board",
        "description": "The board from which the fan is disconnected at J5 for the leak test.",
        "category": "electrical"
      },
      {
        "component_id": "comp_torch",
        "name": "Torch",
        "description": "The torch used for test cuts and which may be replaced to check whether low air pressure persists.",
        "category": "cutting"
      },
      {
        "component_id": "comp_torch_lead",
        "name": "Torch lead",
        "description": "The lead containing the gas supply fitting and connected to the gas supply line.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_nozzle",
        "name": "Nozzle",
        "description": "The nozzle at the end of the torch, identified as a dangerous-voltage hazard during testing.",
        "category": "cutting"
      }
    ]
  },
  "relations": []
}
